const customTheme = {
  '--w3o-background-color': '#3b724b',
  '--w3o-foreground-color': '#206735',
  '--w3o-text-color': '#1a1d26',
  '--w3o-border-color': '#4fa467',
  '--w3o-action-color': '#6ee38c',
  '--w3o-border-radius': '0',
  '--w3o-font-family': 'DOS'
};

export function init() {
  onboard.value = initOnboard({
    wallets: [ injected ],
    chains,
    appMetadata,
    theme: customTheme,
    connect: {
      autoConnectAllPreviousWallet: true
    },
    accountCenter: {
      desktop: {
        enabled: true,
        position: 'topRight',
        minimal: false
      },
      mobile: {
        enabled: true,
        position: 'topRight',
        minimal: false
      }
    }
  });
}

function setWatchers() {
  const { connectedWallet } = useOnboard();

  watchEffect(async () => {
    if (connectedWallet.value) {
      const p = new ethers.BrowserProvider(connectedWallet.value.provider, 'any');
      // p.on('debug', console.log);
      signer.value = await p.getSigner();

      provider.value = new ethers.JsonRpcProvider(GNOSIS.rpcUrl, { chainId: GNOSIS.id, name: GNOSIS.label });

      chainId.value = parseInt(connectedWallet.value.provider.chainId, 16) || null;
      provider.value.chainId = chainId.value;

      address.value = connectedWallet.value.accounts[0].address;

    } else {
      provider.value = null;
      chainId.value = null;
      address.value = null;
      signer.value = null;
    }
  });

  isWatchesSet = true;
}

export function useWallet() {
  if (!isWatchesSet) {
    setWatchers();
  }

  return {
    address,
    provider,
    signer,
    chainId
  };
}
